    apiEndpoint: Uri.parse('https://api.ain.example/v1'),
    displayName: () => 'AIN',
  );
  return HostSessionState(
    provider: const CustomProvider(
      id: 'host',
      name: 'AIN',
      baseUrl: 'https://api.ain.example/v1',
      modelId: 'ain/ain_flash',
      provenance: 'host',
      kind: 'host-session',
    ),
    bridgedKey: bridgedKey,
    connection: connection,
  );
}

StreamFunction _errorStream(String errorText) {
  return (model, context, {cancelToken}) {
    final stream = AssistantMessageEventStream();
    stream.push(
      ErrorEvent(
        reason: StopReason.error,
        error: AssistantMessage(
          content: const [],
          api: model.api,
          provider: model.provider,
          model: model.id,
          usage: Usage.zero,
          stopReason: StopReason.error,
          errorMessage: errorText,
          timestamp: DateTime.now(),
        ),
      ),
    );
    stream.end();
    return stream;
  };
}

