import 'package:flutter_agent_harness/flutter_agent_harness.dart';

void main() {
  // The host answers the profile's quota shape: 429 + limit_reached.
  final body = '{"error":{"code":"limit_reached","message":"out"}}';
  final rateLimit = parseRateLimitInfo(
    statusCode: 429,
    body: body,
    headers: const {},
  );
  final error = ProviderHttpError(
    429,
    body,
    rateLimit: rateLimit,
    requestUrl: Uri.parse('https://api.ain.example/v1/chat/completions'),
  );
  final text = formatProviderError(error);
  // The quoted text from the test fixture / _validateStreamResponse path:
  print('PROBE rateLimit!=null: ${rateLimit != null}');
  print('PROBE decorated text: ${text.replaceAll('\n', ' | ')}');
  print('PROBE contains errorCode: ${text.contains('limit_reached')}');
  // Leading status still parses (needed by _leadingStatus):
  print('PROBE leadingStatus: ${RegExp(r'^(\d{3}):').firstMatch(text)?.group(1)}');
}

